import { announce, definePrimitive } from "@ui-sdk/core"

import { unavailable } from "@/lib/action-refusal"

type DeviceDecision = "approve" | "deny"

type DeviceApprovalOptions = {
  /** Approves the device; a returned Promise keeps the block pending, and a rejection shows the error. */
  onApprove?: () => unknown
  /** Denies the device, with the same pending and error handling. */
  onDeny?: () => unknown
  /** Runs once, when the request expires. */
  onExpire?: () => void
  /** Why approving waits, like codes that don't match yet; `null` when nothing stops it. */
  approveBlocked?: string | null
  expiredAnnouncement?: string
}

type DeviceApprovalState = {
  /** The decision being sent. */
  pending: DeviceDecision | null
  /** The decision the app accepted. */
  decided: DeviceDecision | null
  error: unknown
  expired: boolean
}

const isThenable = (value: unknown): value is PromiseLike<unknown> =>
  typeof value === "object" && value !== null && "then" in value && typeof value.then === "function"

const pastTense: Record<DeviceDecision, string> = { approve: "approved", deny: "denied" }

const deviceApproval = definePrimitive({
  name: "device-approval",
  options: {
    onApprove: "callback",
    onDeny: "callback",
    onExpire: "callback",
    approveBlocked: "value",
    expiredAnnouncement: "string",
  },
  controlled: ["pending", "decided", "expired"],
  state: (_options: DeviceApprovalOptions): DeviceApprovalState => ({
    pending: null,
    decided: null,
    error: null,
    expired: false,
  }),
  api: (context) => {
    let destroyed = false
    context.onDestroy(() => {
      destroyed = true
    })

    const decide = (decision: DeviceDecision, event: Event | undefined): Promise<DeviceDecision> | boolean => {
      const call = { event }
      const { pending, decided, expired } = context.store.get()
      if (decided !== null) {
        return unavailable(decision, `isn't available: the device was already ${pastTense[decided]}`, call)
      }
      if (pending !== null) return unavailable(decision, "isn't available while a decision is being sent", call)
      if (expired) return unavailable(decision, "isn't available: the request has expired", call)
      const options = context.options()
      const blocked = decision === "approve" ? options.approveBlocked : null
      if (blocked) return unavailable(decision, `isn't available: ${blocked}`, call)
      const run = decision === "approve" ? options.onApprove : options.onDeny
      if (!run)
        return unavailable(
          decision,
          `isn't available: the block has no on${decision === "approve" ? "Approve" : "Deny"}`,
          call,
        )
      context.store.set({ pending: decision, error: null })
      let result: unknown
      try {
        result = run()
      } catch (error) {
        context.store.set({ pending: null, error })
        return Promise.reject(error instanceof Error ? error : new Error(String(error)))
      }
      if (!isThenable(result)) {
        context.store.set({ pending: null, decided: decision })
        return true
      }
      return Promise.resolve(result).then(
        () => {
          if (!destroyed) context.store.set({ pending: null, decided: decision })
          return decision
        },
        (error: unknown) => {
          if (!destroyed) context.store.set({ pending: null, error })
          throw error
        },
      )
    }

    return {
      /** Approves the device through `onApprove`. The Approve button asks an agent's person first. */
      approve(event?: Event) {
        return decide("approve", event)
      },
      /** Denies the device through `onDeny`. */
      deny(event?: Event) {
        return decide("deny", event)
      },
      /** Marks the request expired, once: approving stops, `onExpire` runs and the expiry is announced. */
      expire() {
        if (context.store.get().expired) return
        context.store.set({ expired: true })
        const { onExpire, expiredAnnouncement } = context.options()
        if (expiredAnnouncement) announce(expiredAnnouncement)
        onExpire?.()
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, DeviceApprovalState>({
      state: (state) => ({ ...state }),
      attrs: (state) => ({
        role: "group",
        "aria-busy": state.pending === null ? undefined : "true",
        "data-pending": state.pending ?? undefined,
        "data-decided": state.decided ?? undefined,
        "data-expired": state.expired ? "" : undefined,
      }),
    }),
  }),
  agent: { actions: ["deny"] },
})

type DeviceApprovalApproveOptions = {
  /** The block's `approve`, which decides whether it runs. */
  approve?: (event?: Event) => unknown
  /** Disables the person's button; an agent's step still reaches `approve`, which says why it refuses. */
  blocked?: boolean
  pending?: boolean
}

type DeviceApprovalApproveState = { blocked: boolean; pending: boolean }

const deviceApprovalApprove = definePrimitive({
  name: "device-approval-approve",
  options: { approve: "callback", blocked: "boolean", pending: "boolean" },
  state: (options: DeviceApprovalApproveOptions): DeviceApprovalApproveState => ({
    blocked: options.blocked ?? false,
    pending: options.pending ?? false,
  }),
  sync: (options) => ({ blocked: options.blocked ?? false, pending: options.pending ?? false }),
  api: (context) => ({
    /** Approves the device; an agent's step needs a person, through the button's `data-agent-confirm`. */
    approve(event?: Event) {
      const { approve } = context.options()
      if (!approve) return unavailable("approve", "isn't available: the block renders its own actions", { event })
      return approve(event)
    },
  }),
  slots: (slot) => ({
    root: slot<{}, DeviceApprovalApproveState>({
      state: (state) => ({ ...state }),
      attrs: (state) => ({
        role: "group",
        "data-blocked": state.blocked ? "" : undefined,
        "data-pending": state.pending ? "" : undefined,
      }),
    }),
  }),
  agent: { actions: ["approve"] },
})

export { deviceApproval, deviceApprovalApprove }
export type {
  DeviceApprovalApproveOptions,
  DeviceApprovalApproveState,
  DeviceApprovalOptions,
  DeviceApprovalState,
  DeviceDecision,
}

"use client"

import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import { BanIcon, CheckIcon } from "lucide-react"
import { useId, type ReactNode } from "react"

import { Button } from "@/components/ui/button"
import { deviceApprovalApprove } from "@/components/ui/device-approval-primitive"
import { cn } from "@/lib/utils"

type DevicePermission = {
  id: string
  label: ReactNode
  description?: ReactNode
  /** Why it's withheld, like "Your role can't grant this". */
  reason?: ReactNode
}

const approveAttributes = (agentConfirm: string): Record<`data-${string}`, string> => ({
  "data-slot": "device-approval-approve",
  "data-agent-confirm": agentConfirm,
})

const ignoreRefusal = () => undefined

function hasContent(node: ReactNode) {
  return node !== undefined && node !== null && node !== false
}

const permissionLook = {
  granted: {
    icon: <CheckIcon strokeWidth={2.5} />,
    className: "border-success-border bg-success-soft text-success-soft-foreground",
  },
  withheld: {
    icon: <BanIcon strokeWidth={2.5} />,
    className: "border-warning-border bg-warning-soft text-warning-soft-foreground",
  },
}

function PermissionSection({
  kind,
  heading,
  permissions,
}: {
  kind: "granted" | "withheld"
  heading?: ReactNode
  permissions: readonly DevicePermission[]
}) {
  const headingId = useId()
  if (permissions.length === 0) return null
  const look = permissionLook[kind]
  const labelledBy = hasContent(heading) ? headingId : undefined
  return (
    <section
      data-slot={`device-approval-${kind}`}
      aria-labelledby={labelledBy}
      className="flex min-w-0 flex-col gap-items"
    >
      {labelledBy === undefined ? null : (
        <h3 id={headingId} className="text-title-sm">
          {heading}
        </h3>
      )}
      <ul aria-labelledby={labelledBy} className="flex flex-col gap-items">
        {permissions.map((permission) => (
          <li key={permission.id} data-slot="device-approval-permission" className="flex items-start gap-items">
            <span
              aria-hidden="true"
              className={cn(
                "flex size-6 shrink-0 items-center justify-center rounded-full border [&_svg]:size-3.5",
                look.className,
              )}
            >
              {look.icon}
            </span>
            <span className="flex min-w-0 flex-col">
              <span className="text-body font-medium">{permission.label}</span>
              {hasContent(permission.description) ? (
                <span className="text-body-sm text-muted-foreground">{permission.description}</span>
              ) : null}
              {hasContent(permission.reason) ? (
                <span data-slot="device-approval-reason" className="text-caption text-muted-foreground">
                  {permission.reason}
                </span>
              ) : null}
            </span>
          </li>
        ))}
      </ul>
    </section>
  )
}

function ApproveButton({
  approve,
  blocked,
  pending,
  describedBy,
  agentConfirm,
  children,
}: {
  approve: (event?: Event) => unknown
  blocked: boolean
  pending: boolean
  describedBy?: string
  agentConfirm: string
  children: ReactNode
}) {
  const handle = usePrimitive(deviceApprovalApprove, { approve, blocked, pending })
  const buttonId = useId()
  return usePart(
    handle,
    "root",
    {},
    {
      ...approveAttributes(agentConfirm),
      "aria-labelledby": buttonId,
      className: "contents",
      children: (
        <Button
          id={buttonId}
          aria-describedby={describedBy}
          data-agent-hidden=""
          className="narrow:w-full"
          disabled={blocked}
          focusableWhenDisabled
          loading={pending}
          onClick={(event) => {
            const result = handle.api.approve(event.nativeEvent)
            if (result instanceof Promise) result.then(undefined, ignoreRefusal)
          }}
        >
          <CheckIcon />
          {children}
        </Button>
      ),
    },
    "span",
  )
}

export { ApproveButton, PermissionSection }
export type { DevicePermission }

import { createChange, definePrimitive, type ChangeDetails } from "@ui-sdk/core"

import { settled, unavailable } from "@/lib/action-refusal"

type DeviceApprovalItemEntry = { value: string; label: string }

type DeviceApprovalItemsChangeReason = "press" | "imperative"

type ItemCall = { reason?: DeviceApprovalItemsChangeReason; event?: Event }

/** An item that can't be selected, with why. */
type DeviceApprovalUnselectable = { id: string; reason: string }

type DeviceApprovalItemsOptions = {
  /** Every item, by id and label, as agents read them. */
  items?: readonly DeviceApprovalItemEntry[]
  unselectable?: readonly DeviceApprovalUnselectable[]
  /** Why nothing can change now, like a decision already sent; `null` while the person can choose. */
  locked?: string | null
  selectedIds?: readonly string[]
  onSelectedIdsChange?: (ids: string[], details: ChangeDetails<DeviceApprovalItemsChangeReason>) => void
}

type DeviceApprovalItemsState = {
  selectedIds: readonly string[]
  /** The labels of the selected items, for agents. */
  selected: readonly string[]
}

/** A marked item and its confirmations as agents name them: the text when it's a string, `null` otherwise. */
type DeviceApprovalMarkedItem = { id: string; confirmations: readonly (string | null)[] }

type DeviceApprovalMarkersOptions = {
  items?: readonly DeviceApprovalItemEntry[]
  /** The items whose selection needs its own confirmations, each ticked. */
  marked?: readonly DeviceApprovalMarkedItem[]
  selectedIds?: readonly string[]
  locked?: string | null
  /** The ticked confirmations, as `confirmationKey(id, index)`. */
  ticked?: readonly string[]
  onTickedChange?: (keys: string[], details: ChangeDetails<DeviceApprovalItemsChangeReason>) => void
}

type DeviceApprovalMarkersState = {
  ticked: readonly string[]
  /** The ids of the marked items with every confirmation ticked. */
  confirmedIds: readonly string[]
  /** Their labels, for agents. */
  confirmed: readonly string[]
  /** What the selected marked items still wait for, like "OpenAI key: Replace the existing key", for agents. */
  missing: readonly string[]
}

const labelsOf = (items: readonly DeviceApprovalItemEntry[] | undefined, ids: readonly string[]) =>
  (items ?? []).filter((item) => ids.includes(item.value)).map((item) => item.label)

function findItem(items: readonly DeviceApprovalItemEntry[] | undefined, idOrLabel: unknown) {
  if (typeof idOrLabel !== "string") return undefined
  const label = idOrLabel.toLocaleLowerCase()
  return (
    items?.find((item) => item.value === idOrLabel) ?? items?.find((item) => item.label.toLocaleLowerCase() === label)
  )
}

const toggled = (ids: readonly string[], id: string, checked: boolean) =>
  checked ? [...new Set([...ids, id])] : ids.filter((other) => other !== id)

function awaitingRender(shown: () => readonly string[]) {
  let pending: { shown: readonly string[]; next: readonly string[] } | null = null
  return {
    latest: () => {
      const current = shown()
      return pending !== null && pending.shown === current ? pending.next : current
    },
    asked: (next: readonly string[]) => {
      pending = { shown: shown(), next }
    },
  }
}

const confirmationKey = (id: string, index: number) => `${String(index)}:${id}`

const confirmationName = (text: string | null, index: number) => text ?? `confirmation ${String(index)}`

const everyTicked = (ticked: readonly string[], item: DeviceApprovalMarkedItem) =>
  item.confirmations.every((_, index) => ticked.includes(confirmationKey(item.id, index)))

function markersState(options: DeviceApprovalMarkersOptions, ticked: readonly string[]): DeviceApprovalMarkersState {
  const marked = options.marked ?? []
  const confirmedIds = marked.filter((item) => everyTicked(ticked, item)).map((item) => item.id)
  const missing = marked
    .filter((item) => options.selectedIds?.includes(item.id))
    .flatMap((item) => {
      const label = findItem(options.items, item.id)?.label ?? item.id
      return item.confirmations.flatMap((text, index) =>
        ticked.includes(confirmationKey(item.id, index)) ? [] : [`${label}: ${confirmationName(text, index)}`],
      )
    })
  return { ticked, confirmedIds, confirmed: labelsOf(options.items, confirmedIds), missing }
}

function confirmationIndex(
  marked: DeviceApprovalMarkedItem,
  label: string,
  confirmation: unknown,
): { index: number } | { why: string } {
  const count = marked.confirmations.length
  const range = `from 0 to ${String(count - 1)}`
  if (confirmation === undefined) {
    if (count === 1) return { index: 0 }
    return { why: `needs which confirmation of ${label}: it has ${String(count)}, by index ${range} or by its text` }
  }
  if (typeof confirmation === "number") {
    if (Number.isInteger(confirmation) && confirmation >= 0 && confirmation < count) return { index: confirmation }
    return { why: `has no confirmation ${String(confirmation)} for ${label}: its indexes run ${range}` }
  }
  if (typeof confirmation === "string") {
    const text = confirmation.toLocaleLowerCase()
    const index = marked.confirmations.findIndex((other) => other?.toLocaleLowerCase() === text)
    if (index >= 0) return { index }
    return { why: `has no confirmation ${JSON.stringify(confirmation)} for ${label}` }
  }
  return { why: "takes the confirmation's index or its text" }
}

const deviceApprovalItems = definePrimitive({
  name: "device-approval-items",
  options: {
    items: "value",
    unselectable: "value",
    locked: "value",
    selectedIds: "list",
    onSelectedIdsChange: "callback",
  },
  state: (options: DeviceApprovalItemsOptions): DeviceApprovalItemsState => {
    const selectedIds = options.selectedIds ?? []
    return { selectedIds, selected: labelsOf(options.items, selectedIds) }
  },
  sync: (options) => {
    const selectedIds = options.selectedIds ?? []
    return { selectedIds, selected: labelsOf(options.items, selectedIds) }
  },
  controlled: ["selectedIds", "selected"],
  api: (context) => {
    const change = createChange(context)
    const selection = awaitingRender(() => context.store.get().selectedIds)
    return {
      /** Selects (`checked`, the default) or deselects an item by its id or its label, in any case. */
      select(idOrLabel: unknown, checked: unknown = true, call: ItemCall = {}) {
        if (typeof checked !== "boolean")
          return unavailable("select", "takes true to select and false to deselect", call)
        const { items, unselectable, locked } = context.options()
        const item = findItem(items, idOrLabel)
        if (!item) return unavailable("select", `has no item named ${JSON.stringify(idOrLabel)}`, call)
        if (locked) return unavailable("select", `isn't available: ${locked}`, call)
        const blocked = unselectable?.find((entry) => entry.id === item.value)
        if (blocked)
          return unavailable("select", `isn't available: ${item.label} can't be selected: ${blocked.reason}`, call)
        const current = selection.latest()
        if (current.includes(item.value) === checked) return true
        const details = { reason: call.reason ?? "imperative", event: call.event }
        const next = toggled(current, item.value, checked)
        const changed = change("selectedIds", next, details)
        if (changed !== false) selection.asked(next)
        return settled(changed, "select", details)
      },
      agentItems() {
        return context.options().items ?? []
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, DeviceApprovalItemsState>({
      state: (state) => ({ ...state }),
      attrs: () => ({ role: "group" }),
    }),
  }),
  agent: { actions: ["select"], items: (api) => api.agentItems() },
})

const deviceApprovalMarkers = definePrimitive({
  name: "device-approval-markers",
  options: {
    items: "value",
    marked: "value",
    selectedIds: "value",
    locked: "value",
    ticked: "list",
    onTickedChange: "callback",
  },
  state: (options: DeviceApprovalMarkersOptions): DeviceApprovalMarkersState =>
    markersState(options, options.ticked ?? []),
  sync: (options) => (options.ticked === undefined ? {} : markersState(options, options.ticked)),
  controlled: ["confirmedIds", "confirmed", "missing"],
  api: (context) => {
    const change = createChange(context)
    const ticking = awaitingRender(() => context.store.get().ticked)
    return {
      /**
       * Ticks (`checked`, the default) or clears one confirmation of a selected, marked item, by the item's id or
       * label. `confirmation` is its index in `marker.confirm` or its text, in any case; it can be left out when the
       * item has only one. The group carries `data-agent-confirm`, so an agent's step waits for a person.
       */
      confirmMarker(idOrLabel: unknown, checked: unknown = true, confirmation?: unknown, call: ItemCall = {}) {
        if (typeof checked !== "boolean") {
          return unavailable("confirmMarker", "takes true to confirm and false to clear the confirmation", call)
        }
        const { items, marked, selectedIds, locked } = context.options()
        const item = findItem(items, idOrLabel)
        if (!item) return unavailable("confirmMarker", `has no item named ${JSON.stringify(idOrLabel)}`, call)
        if (locked) return unavailable("confirmMarker", `isn't available: ${locked}`, call)
        const entry = marked?.find((candidate) => candidate.id === item.value)
        if (!entry) return unavailable("confirmMarker", `isn't available: ${item.label} has nothing to confirm`, call)
        if (!selectedIds?.includes(item.value)) {
          return unavailable("confirmMarker", `isn't available: ${item.label} isn't selected`, call)
        }
        const target = confirmationIndex(entry, item.label, confirmation)
        if ("why" in target) return unavailable("confirmMarker", target.why, call)
        const key = confirmationKey(item.value, target.index)
        const current = ticking.latest()
        if (current.includes(key) === checked) return true
        const details = { reason: call.reason ?? "imperative", event: call.event }
        const next = toggled(current, key, checked)
        const changed = change("ticked", next, details)
        if (changed !== false) {
          ticking.asked(next)
          if (context.options().ticked === undefined) context.store.set(markersState(context.options(), next))
        }
        return settled(changed, "confirmMarker", details)
      },
      agentItems() {
        const { items, marked } = context.options()
        return (items ?? []).filter((item) => marked?.some((entry) => entry.id === item.value))
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, DeviceApprovalMarkersState>({
      state: (state) => ({ ...state }),
      attrs: () => ({ role: "group" }),
    }),
  }),
  agent: { actions: ["confirmMarker"], items: (api) => api.agentItems() },
})

export { confirmationKey, deviceApprovalItems, deviceApprovalMarkers }
export type {
  DeviceApprovalItemEntry,
  DeviceApprovalItemsChangeReason,
  DeviceApprovalItemsOptions,
  DeviceApprovalItemsState,
  DeviceApprovalMarkedItem,
  DeviceApprovalMarkersOptions,
  DeviceApprovalMarkersState,
  DeviceApprovalUnselectable,
}

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import { useId, useState, type ReactNode } from "react"

import { Badge } from "@/components/ui/badge"
import { CheckboxRow } from "@/components/ui/checkbox-row"
import {
  confirmationKey,
  deviceApprovalItems,
  deviceApprovalMarkers,
  type DeviceApprovalItemsChangeReason,
  type DeviceApprovalItemsState,
  type DeviceApprovalMarkersState,
} from "@/components/ui/device-approval-items-primitive"

/** Something the person ticks to include, like a key to upload. */
type DeviceConsentItem = {
  id: string
  /** Names its checkbox; agents select it by this or by `id`, in any case. */
  label: string
  description?: ReactNode
  /** At the end of the row, like a SecretFingerprint. */
  detail?: ReactNode
  /** Keeps it from being selected; the reason shows under the label and describes the checkbox. */
  disabled?: { reason: string }
  marker?: DeviceConsentMarker
}

/**
 * For an item that replaces something that already exists: `label` shows as a warning badge, like "Replace", and
 * `confirm` labels a checkbox, like "Replace the existing key", that the person ticks once it's selected. A list gives
 * one checkbox per entry, each to be ticked; wrap a label made of several nodes in a fragment.
 */
type DeviceConsentMarker = { label: ReactNode; confirm: ReactNode | readonly ReactNode[] }

/** A selected marked item that still waits: `unticked` holds the indexes in `marker.confirm` not ticked yet. */
type DeviceConsentUnconfirmed = { id: string; label: string; unticked: number[] }

/** The consent items' visible text. None has a default: pass it in the page's language. */
type DeviceConsentText = {
  /** The heading over the items. */
  items?: ReactNode
  /** Why Approve waits while nothing is selected; shown beside the actions and read by an agent. */
  nothingSelected?: string
  /** Why Approve waits for marked items without every confirmation ticked, or a function of their labels. */
  unconfirmed?: string | ((labels: string[], unconfirmed: DeviceConsentUnconfirmed[]) => string)
}

/** Names for screen readers and agents; English by default. */
type DeviceConsentLabels = {
  /** Names the items' group when `text.items` gives no heading. */
  items: string
  /** Names the group of marker confirmations. */
  markers: string
  /** What a person approves when an agent ticks a marker's confirmation. */
  confirmMarkers: string
}

const deviceConsentLabels: DeviceConsentLabels = {
  items: "Items",
  markers: "Confirmations",
  confirmMarkers: "Confirms replacing something that already exists",
}

type ConsentSelection = {
  items?: readonly DeviceConsentItem[]
  selected?: readonly string[]
  defaultSelected?: readonly string[]
  onSelectedChange?: (ids: string[], details: ChangeDetails<DeviceApprovalItemsChangeReason>) => void
}

const noIds: readonly string[] = []

const sameIds = (a: readonly string[], b: readonly string[]) => a.length === b.length && a.every((id) => b.includes(id))

const confirmationsOf = (item: DeviceConsentItem): readonly ReactNode[] => {
  const confirm = item.marker?.confirm
  if (confirm === undefined) return []
  return Array.isArray(confirm) ? confirm : [confirm]
}

const keysOf = (item: DeviceConsentItem) => confirmationsOf(item).map((_, index) => confirmationKey(item.id, index))

const agentText = (node: ReactNode) =>
  typeof node === "string" ? node : typeof node === "number" ? String(node) : null

/** The selected ids, and the ticked confirmations that belong to them: an item that leaves the selection loses them. */
function useConsentItems({ items, selected, defaultSelected, onSelectedChange }: ConsentSelection) {
  const [ownSelected, setOwnSelected] = useState(defaultSelected ?? noIds)
  const selectedIds = (selected ?? ownSelected).filter((id) => items?.some((item) => item.id === id) ?? false)
  const [confirmation, setConfirmation] = useState({ selectedIds, ticked: noIds })
  let ticked = confirmation.ticked
  if (!sameIds(confirmation.selectedIds, selectedIds)) {
    const kept = (items ?? []).filter((item) => selectedIds.includes(item.id)).flatMap(keysOf)
    ticked = ticked.filter((key) => kept.includes(key))
    setConfirmation({ selectedIds, ticked })
  }
  const confirmedIds = (items ?? [])
    .filter((item) => item.marker && selectedIds.includes(item.id) && keysOf(item).every((key) => ticked.includes(key)))
    .map((item) => item.id)
  return {
    selectedIds,
    ticked,
    confirmedIds,
    select: (ids: string[], details: ChangeDetails<DeviceApprovalItemsChangeReason>) => {
      onSelectedChange?.(ids, details)
      if (!details.canceled && selected === undefined) setOwnSelected(ids)
    },
    tick: (keys: string[]) => setConfirmation({ selectedIds, ticked: keys }),
  }
}

type Waiting = { item: DeviceConsentItem; unticked: number[] }

function missingConfirmations({ item, unticked }: Waiting) {
  const confirmations = confirmationsOf(item)
  if (confirmations.length === 1) return null
  const names = unticked.map((index) =>
    JSON.stringify(agentText(confirmations[index]) ?? `confirmation ${String(index)}`),
  )
  const more = unticked.length === 1 ? "1 more confirmation" : `${String(unticked.length)} more confirmations`
  return `${item.label} needs ${more} ticked: ${names.join(", ")}`
}

function unconfirmedReason(waiting: readonly Waiting[]) {
  const single = waiting.filter((entry) => missingConfirmations(entry) === null).map((entry) => entry.item.label)
  const several = waiting.flatMap((entry) => missingConfirmations(entry) ?? [])
  const singleReason = single.length === 0 ? [] : [`${single.join(", ")} needs its confirmation ticked`]
  return [...singleReason, ...several].join("; ")
}

/** Why the items keep Approve off: `reason` for an agent, `shown` when the page gave the words. */
function consentBlocked(
  items: readonly DeviceConsentItem[] | undefined,
  selectedIds: readonly string[],
  ticked: readonly string[],
  text: DeviceConsentText,
): { reason: string; shown?: string } | null {
  if (items === undefined) return null
  if (selectedIds.length === 0)
    return { reason: text.nothingSelected ?? "nothing is selected", shown: text.nothingSelected }
  const waiting = items.flatMap((item): Waiting[] => {
    if (!selectedIds.includes(item.id)) return []
    const unticked = keysOf(item).flatMap((key, index) => (ticked.includes(key) ? [] : [index]))
    return unticked.length === 0 ? [] : [{ item, unticked }]
  })
  if (waiting.length === 0) return null
  const unconfirmed = waiting.map(({ item, unticked }) => ({ id: item.id, label: item.label, unticked }))
  const shown =
    typeof text.unconfirmed === "function"
      ? text.unconfirmed(
          unconfirmed.map((entry) => entry.label),
          unconfirmed,
        )
      : text.unconfirmed
  return { reason: shown ?? unconfirmedReason(waiting), shown }
}

type ConsentItemsProps = {
  items: readonly DeviceConsentItem[]
  selectedIds: readonly string[]
  ticked: readonly string[]
  onSelectedIdsChange: (ids: string[], details: ChangeDetails<DeviceApprovalItemsChangeReason>) => void
  onTickedChange: (keys: string[]) => void
  /** Why nothing can change now, like a decision already sent. */
  locked: string | null
  heading?: ReactNode
  labels: DeviceConsentLabels
}

const itemsAttributes: Record<`data-${string}`, string> = { "data-slot": "device-approval-items" }

const markersAttributes = (agentConfirm: string): Record<`data-${string}`, string> => ({
  "data-slot": "device-approval-markers",
  "data-agent-confirm": agentConfirm,
})

function MarkerConfirmations({
  items,
  selectedIds,
  ticked,
  onTickedChange,
  locked,
  labels,
}: Omit<ConsentItemsProps, "onSelectedIdsChange" | "heading">) {
  const marked = items.filter((item) => confirmationsOf(item).length > 0)
  const handle = usePrimitive(deviceApprovalMarkers, {
    items: items.map((item) => ({ value: item.id, label: item.label })),
    marked: marked.map((item) => ({ id: item.id, confirmations: confirmationsOf(item).map(agentText) })),
    selectedIds,
    locked,
    ticked,
    onTickedChange: (keys) => onTickedChange(keys),
  })
  return usePart(
    handle,
    "root",
    {},
    {
      ...markersAttributes(labels.confirmMarkers),
      "aria-label": labels.markers,
      className: "contents",
      children: (state: DeviceApprovalMarkersState) => {
        const pending = marked.filter((item) => selectedIds.includes(item.id))
        if (pending.length === 0) return null
        return (
          <div className="flex flex-col gap-items border-s-2 border-warning-border ps-items">
            {pending.flatMap((item) =>
              confirmationsOf(item).map((confirmation, index) => (
                <CheckboxRow
                  key={confirmationKey(item.id, index)}
                  data-agent-hidden=""
                  label={confirmation}
                  description={item.label}
                  checked={state.ticked.includes(confirmationKey(item.id, index))}
                  disabled={locked !== null}
                  onCheckedChange={(checked, details) =>
                    handle.api.confirmMarker(item.id, checked === true, index, {
                      reason: "press",
                      event: details.event,
                    })
                  }
                />
              )),
            )}
          </div>
        )
      },
    },
  )
}

function ConsentItems(props: ConsentItemsProps) {
  const { items, selectedIds, onSelectedIdsChange, locked, heading, labels } = props
  const headingId = useId()
  const handle = usePrimitive(deviceApprovalItems, {
    items: items.map((item) => ({ value: item.id, label: item.label })),
    unselectable: items.flatMap((item) => (item.disabled ? [{ id: item.id, reason: item.disabled.reason }] : [])),
    locked,
    selectedIds,
    onSelectedIdsChange,
  })
  const hasHeading = heading !== undefined && heading !== null && heading !== false
  const list = usePart(
    handle,
    "root",
    {},
    {
      ...itemsAttributes,
      "aria-labelledby": hasHeading ? headingId : undefined,
      "aria-label": hasHeading ? undefined : labels.items,
      className: "flex min-w-0 flex-col gap-items",
      children: (state: DeviceApprovalItemsState) => (
        <>
          {hasHeading ? (
            <h3 id={headingId} className="text-title-sm">
              {heading}
            </h3>
          ) : null}
          <ul className="flex flex-col gap-items">
            {items.map((item) => (
              <li key={item.id} data-slot="device-approval-item">
                <CheckboxRow
                  data-agent-hidden=""
                  label={item.label}
                  description={item.description}
                  trailing={
                    item.detail === undefined && item.marker === undefined ? undefined : (
                      <>
                        {item.detail}
                        {item.marker ? <Badge tone="warning">{item.marker.label}</Badge> : null}
                      </>
                    )
                  }
                  disabled={item.disabled ?? locked !== null}
                  checked={state.selectedIds.includes(item.id)}
                  onCheckedChange={(checked, details) =>
                    handle.api.select(item.id, checked === true, { reason: "press", event: details.event })
                  }
                />
              </li>
            ))}
          </ul>
        </>
      ),
    },
  )
  return (
    <div className="flex min-w-0 flex-col gap-items">
      {list}
      <MarkerConfirmations {...props} />
    </div>
  )
}

export { ConsentItems, consentBlocked, deviceConsentLabels, useConsentItems }
export type { DeviceConsentItem, DeviceConsentLabels, DeviceConsentMarker, DeviceConsentText, DeviceConsentUnconfirmed }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import { CircleSlashIcon, ClockAlertIcon, MonitorSmartphoneIcon, TriangleAlertIcon } from "lucide-react"
import { useId, useState, type ReactNode } from "react"

import { Alert, AlertDescription } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  ConsentItems,
  consentBlocked,
  deviceConsentLabels,
  useConsentItems,
  type DeviceConsentItem,
  type DeviceConsentLabels,
  type DeviceConsentText,
} from "@/components/ui/device-approval-items"
import type { DeviceApprovalItemsChangeReason } from "@/components/ui/device-approval-items-primitive"
import { ApproveButton, PermissionSection, type DevicePermission } from "@/components/ui/device-approval-parts"
import {
  deviceApproval,
  type DeviceApprovalState,
  type DeviceDecision,
} from "@/components/ui/device-approval-primitive"
import { ExpiryCountdown } from "@/components/ui/expiry-countdown"
import {
  PairingCode,
  type PairingCodeConfirmText,
  type PairingCodeEnterText,
  type PairingCodeLabels,
} from "@/components/ui/pairing-code"
import { useExpiry } from "@/components/ui/use-expiry"
import { rejectionContent, type RejectionFallback } from "@/lib/rejection-content"
import { cn } from "@/lib/utils"

/** The device asking for access. */
type DeviceInfo = {
  name: string
  /** Free text, like "Desktop" or "Node". */
  kind?: string
  /** Replaces the default device icon. */
  icon?: ReactNode
  /** A line under the name, like where and when it asked. */
  detail?: ReactNode
}

type DevicePermissionList = "granted" | "withheld"

type DevicePermissionHeadings = {
  /** The heading over what the device gets. */
  granted: ReactNode
  /** The heading over what it asked for and won't get. */
  withheld: ReactNode
}

/**
 * The block's visible text. None has a default: pass it in the page's language. `Lists` names the permission lists the
 * block shows, whose headings it then needs: both by default, `never` for a block with `items` only.
 */
type DeviceApprovalText<Lists extends DevicePermissionList = DevicePermissionList> = DeviceApprovalBaseText &
  Pick<DevicePermissionHeadings, Lists>

type DeviceApprovalBaseText = DeviceConsentText & {
  /** Under the device, like "This device asked to connect to your account." */
  description?: ReactNode
  /** Names the pairing code, when `code` is given; "Pairing code" by default. */
  code?: string
  approve: ReactNode
  deny: ReactNode
  /** What a person approves when an agent approves, like "Gives Studio laptop access to your account". */
  approveAgentConfirm: string
  /**
   * Shown in a live alert when approving or denying fails with something other than a string or a node, which show as
   * they are; a function of the error picks one per failure.
   */
  error: RejectionFallback
  /** The time left, from the milliseconds left and the same as `m:ss`; shown each second and read once a minute. */
  expiresIn?: (remainingMs: number, formatted: string) => string
  /** Shown, and read, once `expiresAt` passes. */
  expired?: string
  /** Shown, and read, once the app accepts the approval. */
  approved?: ReactNode
  denied?: ReactNode
}

/** Names for screen readers and agents; English by default. `codeLabels` holds the inner PairingCode's. */
type DeviceApprovalLabels = DeviceConsentLabels & {
  /** Names the pairing code; `text.code` wins over it. */
  code: string
}

const deviceApprovalLabels: DeviceApprovalLabels = { ...deviceConsentLabels, code: "Pairing code" }

/** What `onApprove` receives: the selected item ids, and those of them whose marker confirmation is ticked. */
type DeviceApprovalDecision = { selected: string[]; confirmed: string[] }

/** What a consumer's own `actions` can render from. */
type DeviceApprovalActionState = {
  expired: boolean
  /** Whether the codes match, with `code` and `compare`; `null` without a comparison or before an answer. */
  codesMatch: boolean | null
  /** True while the app (`approveBlocked`), the comparison, the items or the expiry stops an approval. */
  approveBlocked: boolean
  /** The selected item ids, with `items`. */
  selected: string[]
  /** The selected marked items whose confirmation is ticked. */
  confirmed: string[]
}

type DeviceApprovalBaseProps = {
  device: DeviceInfo
  /** The pairing code shown on the other screen, rendered with PairingCode. */
  code?: string
  groupSize?: number
  separator?: string
  /** Keeps the code and its comparison from agents; on by default, so an agent never reads or types the code. */
  agentHidden?: boolean
  /**
   * Things the person ticks to include, like keys to upload, under `text.items`. Approve waits until one is selected
   * and every selected item with a `marker` has its confirmation ticked.
   */
  items?: readonly DeviceConsentItem[]
  /** The selected item ids, to control the selection. */
  selected?: readonly string[]
  defaultSelected?: readonly string[]
  /** The new selected ids; `details.cancel()` keeps the old ones, and an agent's step then fails with why. */
  onSelectedChange?: (ids: string[], details: ChangeDetails<DeviceApprovalItemsChangeReason>) => void
  /** A security warning, shown in a warning Alert. */
  warning?: ReactNode
  /** When the request expires; approving stops then. */
  expiresAt?: Date | number
  /** Runs once, when `expiresAt` passes. */
  onExpire?: () => void
  /** Turns Approve off for a reason of the app's, like an account that can't grant any requested permission. */
  approveBlocked?: boolean
  /**
   * Why `approveBlocked` stops approving, in the page's language: shown beside the actions, describing Approve, and the
   * message an agent's `approve` fails with. Without it, nothing shows and an agent reads an English reason.
   */
  approveBlockedReason?: string
  text: DeviceApprovalText<never>
  labels?: Partial<DeviceApprovalLabels>
  /** The inner PairingCode's names (its copy button and the spelled-out code), merged over its English defaults. */
  codeLabels?: Partial<PairingCodeLabels>
  className?: string
}

type DeviceApprovalCompareProps =
  | { compare?: undefined; compareText?: undefined }
  | { compare: "confirm"; compareText: PairingCodeConfirmText; onConfirm?: (matches: boolean) => unknown }
  | { compare: "enter"; compareText: PairingCodeEnterText; onMatchChange?: (matches: boolean) => void }

type DeviceApprovalActionProps =
  | {
      /**
       * Approves the device; a returned Promise keeps the block pending, and a rejection shows in the error alert: a
       * string or a node as it is, anything else through `text.error`. With `items`, it gets what was selected.
       */
      onApprove: (decision: DeviceApprovalDecision) => unknown
      onDeny: () => unknown
      actions?: undefined
    }
  | {
      /** Your own actions in place of Approve and Deny. Mark an approve control with `data-agent-confirm`. */
      actions: ReactNode | ((state: DeviceApprovalActionState) => ReactNode)
      onApprove?: undefined
      onDeny?: undefined
    }

type DeviceApprovalPermissionProps<List extends DevicePermissionList> =
  | { [Key in List]?: undefined }
  | ({ [Key in List]?: readonly DevicePermission[] } & { text: Pick<DevicePermissionHeadings, List> })

type DeviceApprovalProps = DeviceApprovalBaseProps &
  DeviceApprovalCompareProps &
  DeviceApprovalActionProps &
  DeviceApprovalPermissionProps<"granted"> &
  DeviceApprovalPermissionProps<"withheld">

const rootAttributes: Record<`data-${string}`, string> = { "data-slot": "device-approval" }

const noPermissions: readonly DevicePermission[] = []

const ignoreRefusal = () => undefined

function hasContent(node: ReactNode) {
  return node !== undefined && node !== null && node !== false
}

const appBlockedFallback = "the app doesn't allow approving this request"

function compareBlockedReason(compare: DeviceApprovalProps["compare"], codesMatch: boolean | null) {
  if (compare === "confirm" && codesMatch !== true) return "the person hasn't confirmed that the codes match"
  if (compare === "enter" && codesMatch !== true) return "the typed code doesn't match the device's code"
  return null
}

function lockedReason(state: DeviceApprovalState): string | null {
  if (state.decided !== null) return `the device was already ${state.decided === "approve" ? "approved" : "denied"}`
  if (state.pending !== null) return "a decision is being sent"
  return state.expired ? "the request has expired" : null
}

function DeviceApproval(props: DeviceApprovalProps) {
  const {
    device,
    code,
    groupSize,
    separator,
    agentHidden = true,
    granted = noPermissions,
    withheld = noPermissions,
    items,
    warning,
    expiresAt,
    onExpire,
    approveBlocked = false,
    approveBlockedReason,
    labels: overrides,
    codeLabels,
    className,
  } = props
  const text: DeviceApprovalText<never> & Partial<DevicePermissionHeadings> = props.text
  const labels = { ...deviceApprovalLabels, ...overrides }
  const nameId = useId()
  const blockedReasonId = useId()
  const [codesMatch, setCodesMatch] = useState<boolean | null>(null)
  const comparing = code !== undefined && props.compare !== undefined
  const compareBlocked = comparing ? compareBlockedReason(props.compare, codesMatch) : null
  const consent = useConsentItems(props)
  const decision: DeviceApprovalDecision = { selected: [...consent.selectedIds], confirmed: [...consent.confirmedIds] }
  const itemsBlocked = consentBlocked(items, consent.selectedIds, consent.ticked, text)
  const blocked = approveBlocked
    ? (approveBlockedReason ?? appBlockedFallback)
    : (compareBlocked ?? itemsBlocked?.reason ?? null)
  const shownBlockedReason = approveBlocked
    ? approveBlockedReason
    : compareBlocked === null
      ? itemsBlocked?.shown
      : undefined
  const { onApprove } = props
  const handle = usePrimitive(deviceApproval, {
    onApprove: onApprove && (() => onApprove(decision)),
    onDeny: props.onDeny,
    onExpire,
    approveBlocked: blocked,
    expiredAnnouncement: text.expired,
  })
  const { api } = handle
  const expiry = expiresAt instanceof Date ? expiresAt.getTime() : expiresAt
  useExpiry(expiry, () => api.expire())

  const pairing = (() => {
    if (code === undefined) return null
    const shared = { code, label: text.code ?? labels.code, groupSize, separator, agentHidden, labels: codeLabels }
    if (props.compare === "confirm") {
      return (
        <PairingCode
          {...shared}
          compare="confirm"
          text={props.compareText}
          onConfirm={(matches) => {
            setCodesMatch(matches)
            return props.onConfirm?.(matches)
          }}
        />
      )
    }
    if (props.compare === "enter") {
      return (
        <PairingCode
          {...shared}
          compare="enter"
          text={props.compareText}
          onMatchChange={(matches) => {
            setCodesMatch(matches)
            props.onMatchChange?.(matches)
          }}
        />
      )
    }
    return <PairingCode {...shared} />
  })()

  const decidedText = (decided: DeviceDecision | null) => {
    if (decided === "approve") return text.approved
    if (decided === "deny") return text.denied
    return undefined
  }

  return usePart(
    handle,
    "root",
    {},
    {
      ...rootAttributes,
      "aria-labelledby": nameId,
      className: cn("@container flex min-w-0 flex-col gap-group", className),
      children: (state: DeviceApprovalState) => {
        const decidedMessage = decidedText(state.decided)
        const undecided = !state.expired && state.decided === null
        const showBlockedReason = undecided && blocked !== null && shownBlockedReason !== undefined
        const actionState: DeviceApprovalActionState = {
          expired: state.expired,
          codesMatch: comparing ? codesMatch : null,
          approveBlocked: state.expired || blocked !== null,
          ...decision,
        }
        return (
          <>
            <div data-slot="device-approval-device" className="flex min-w-0 items-start gap-items">
              <span
                aria-hidden="true"
                className="flex size-control shrink-0 items-center justify-center rounded-control border bg-muted text-muted-foreground [&_svg]:size-5"
              >
                {device.icon ?? <MonitorSmartphoneIcon />}
              </span>
              <div className="flex min-w-0 flex-col gap-inline">
                <div className="flex min-w-0 flex-wrap items-center gap-inline">
                  <h2 id={nameId} className="min-w-0 text-title-sm break-words">
                    {device.name}
                  </h2>
                  {device.kind === undefined ? null : <Badge variant="secondary">{device.kind}</Badge>}
                </div>
                {hasContent(device.detail) ? (
                  <div className="text-body-sm text-muted-foreground">{device.detail}</div>
                ) : null}
              </div>
            </div>
            {hasContent(text.description) ? (
              <p className="text-body text-muted-foreground">{text.description}</p>
            ) : null}
            {pairing}
            {hasContent(warning) ? (
              <Alert data-slot="device-approval-warning" tone="warning">
                <TriangleAlertIcon />
                <AlertDescription>{warning}</AlertDescription>
              </Alert>
            ) : null}
            {items === undefined ? null : (
              <ConsentItems
                items={items}
                selectedIds={consent.selectedIds}
                ticked={consent.ticked}
                onSelectedIdsChange={consent.select}
                onTickedChange={consent.tick}
                locked={lockedReason(state)}
                heading={text.items}
                labels={labels}
              />
            )}
            {granted.length > 0 || withheld.length > 0 ? (
              <div className="grid min-w-0 gap-group @xl:grid-cols-2">
                <PermissionSection kind="granted" heading={text.granted} permissions={granted} />
                <PermissionSection kind="withheld" heading={text.withheld} permissions={withheld} />
              </div>
            ) : null}
            {state.expired ? (
              <p
                data-slot="device-approval-expired"
                className="flex items-center gap-inline text-body-sm font-medium text-warning-soft-foreground [&_svg]:size-4"
              >
                <ClockAlertIcon />
                {text.expired}
              </p>
            ) : null}
            {!state.expired && expiry !== undefined && text.expiresIn && state.decided === null ? (
              <ExpiryCountdown data-slot="device-approval-countdown" expiresAt={expiry} expiresIn={text.expiresIn} />
            ) : null}
            {state.error === null ? null : (
              <Alert data-slot="device-approval-error" tone="destructive" live>
                <AlertDescription className="text-foreground">
                  {rejectionContent(state.error, text.error)}
                </AlertDescription>
              </Alert>
            )}
            {hasContent(decidedMessage) ? (
              <Alert
                data-slot="device-approval-decided"
                tone={state.decided === "approve" ? "success" : "neutral"}
                live
              >
                <AlertDescription>{decidedMessage}</AlertDescription>
              </Alert>
            ) : null}
            {showBlockedReason ? (
              <p
                id={blockedReasonId}
                data-slot="device-approval-blocked"
                className="flex items-center justify-end gap-inline text-end text-body-sm text-muted-foreground narrow:justify-start narrow:text-start [&_svg]:size-4 [&_svg]:shrink-0"
              >
                <CircleSlashIcon />
                {shownBlockedReason}
              </p>
            ) : null}
            <div
              data-slot="device-approval-actions"
              className="flex flex-wrap items-center justify-end gap-items narrow:flex-col-reverse narrow:items-stretch"
            >
              {props.actions === undefined ? (
                <>
                  <Button
                    variant="outline"
                    className="narrow:w-full"
                    loading={state.pending === "deny"}
                    disabled={state.expired || state.decided !== null || state.pending === "approve"}
                    onClick={(event) => {
                      const result = api.deny(event.nativeEvent)
                      if (result instanceof Promise) result.then(undefined, ignoreRefusal)
                    }}
                  >
                    {text.deny}
                  </Button>
                  <ApproveButton
                    approve={(event) => api.approve(event)}
                    blocked={actionState.approveBlocked || state.decided !== null || state.pending === "deny"}
                    pending={state.pending === "approve"}
                    describedBy={showBlockedReason ? blockedReasonId : undefined}
                    agentConfirm={text.approveAgentConfirm}
                  >
                    {text.approve}
                  </ApproveButton>
                </>
              ) : typeof props.actions === "function" ? (
                props.actions(actionState)
              ) : (
                props.actions
              )}
            </div>
          </>
        )
      },
    },
  )
}

